<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch} from 'vue';
import {api,type KnowledgeVersion} from '../api';
import Button from './ui/Button.vue';import Input from './ui/Input.vue';import CatalogPagination from './CatalogPagination.vue';
const selected=defineModel<number[]>({default:()=>[]});
const historyRows=ref<KnowledgeVersion[]>([]),historyDocument=ref(''),historyError=ref(''),historyLoading=ref(false),historyPage=ref(1),historyTotal=ref<number>();
let historyGeneration=0;
const rows=ref<KnowledgeVersion[]>([]),picked=ref<KnowledgeVersion[]>([]),query=ref(''),error=ref(''),loading=ref(false),page=ref(1),total=ref<number>();
let generation=0,timer:ReturnType<typeof setTimeout>|undefined;
async function load(p=page.value){const gen=++generation;loading.value=true;error.value='';try{const v=await api.knowledge({q:query.value,page:p});if(gen!==generation)return;rows.value=v.items;page.value=v.page;total.value=v.total;}catch(e){if(gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
async function history(v:{documentId:string},p=1){const gen=++historyGeneration;historyDocument.value=v.documentId;historyLoading.value=true;historyError.value='';try{const result=await api.knowledge({documentId:v.documentId,page:p});if(gen!==historyGeneration)return;historyRows.value=result.items;historyPage.value=result.page;historyTotal.value=result.total;}catch(e){if(gen===historyGeneration)historyError.value=(e as Error).message;}finally{if(gen===historyGeneration)historyLoading.value=false;}}
function toggle(v:KnowledgeVersion){if(selected.value.includes(v.id)){selected.value=selected.value.filter(id=>id!==v.id);picked.value=picked.value.filter(k=>k.id!==v.id);}else if(selected.value.length<8){selected.value=[...selected.value,v.id];picked.value=[...picked.value,v];}}
watch(query,()=>{generation++;clearTimeout(timer);timer=setTimeout(()=>void load(1),250);});onMounted(()=>void load());onUnmounted(()=>{historyGeneration++;generation++;clearTimeout(timer);});
</script>
<template><section class="knowledge-picker" aria-label="扫描知识文档">
 <div class="picker-tools"><Input v-model="query" aria-label="搜索知识文档" placeholder="搜索知识文档标题"/><RouterLink to="/knowledge" target="_blank">管理知识文档</RouterLink></div>
 <p>选择固定版本供 SDK 参考，最多 8 份。文档是参考资料，不能扩大本次扫描范围。</p>
 <p v-if="error" role="alert">知识文档读取失败：{{error}} <Button variant="outline" size="sm" @click="load()">重试</Button></p>
 <ul v-if="picked.length" class="picked" aria-label="已选知识文档"><li v-for="v in picked" :key="v.id">{{v.title}} · v{{v.version}} <Button variant="ghost" size="sm" :aria-label="`移除知识文档 ${v.title}`" @click="toggle(v)">移除</Button></li></ul>
 <div class="document-options" :aria-busy="loading"><div v-for="v in rows" :key="v.id" class="option-row"><label><input type="checkbox" :checked="selected.includes(v.id)" :disabled="!selected.includes(v.id)&&selected.length>=8" @change="toggle(v)"/><span>{{v.title}} <small>v{{v.version}} · {{v.sha256.slice(0,12)}}</small></span></label><Button variant="ghost" size="sm" :aria-label="`查看知识文档版本 ${v.title}`" @click="history(v)">版本</Button></div><p v-if="!rows.length&&!loading&&!error">暂无可用知识文档，可先在知识文档页面创建或上传文本。</p></div>
 <section v-if="historyDocument" class="version-options" aria-label="选择知识文档历史版本"><p>选择历史版本 <Button variant="ghost" size="sm" @click="historyDocument='';historyGeneration++">关闭版本列表</Button></p><p v-if="historyError" role="alert">版本读取失败：{{historyError}} <Button variant="outline" size="sm" @click="history({documentId:historyDocument},historyPage)">重试</Button></p><label v-for="v in historyRows" :key="v.id"><input type="checkbox" :checked="selected.includes(v.id)" :disabled="v.archived||(!selected.includes(v.id)&&selected.length>=8)" @change="toggle(v)"/>{{v.title}} · v{{v.version}} · {{v.sha256.slice(0,12)}}</label><CatalogPagination label="知识文档历史版本选择" :page="historyPage" :page-size="50" :total="historyTotal" :loading="historyLoading" @change="p=>history({documentId:historyDocument},p)"/></section>
 <CatalogPagination label="知识文档选择" :page="page" :page-size="50" :total="total" :loading="loading" :unavailable="Boolean(error)" @change="load"/>
</section></template>
<style scoped>
.knowledge-picker{font-size:var(--font-size-sm);color:var(--text-secondary)}.picker-tools{display:flex;align-items:center;gap:var(--space-3)}.picker-tools input{max-width:var(--inspector-width-sm)}a{color:var(--accent-primary);white-space:nowrap}p{line-height:var(--line-height-body);margin:var(--space-2) 0}.document-options{max-height:calc(var(--height-table-row)*6);overflow:auto;border-block:1px solid var(--border-subtle)}.option-row{display:flex;align-items:center;gap:var(--space-2)}.option-row label{flex:1}.version-options{padding:var(--space-3);border:1px solid var(--border-default);margin-top:var(--space-2)}.version-options label{display:flex;align-items:center;gap:var(--space-2);min-height:var(--height-table-row);font-size:var(--font-size-xs)}.document-options label{display:flex;align-items:center;gap:var(--space-2);min-height:var(--height-table-row);padding:var(--space-1) 0}.document-options label:hover{background:var(--surface-hover)}small{font-family:var(--font-mono);margin-left:var(--space-2);color:var(--text-tertiary)}.picked{list-style:none;padding:0;margin:var(--space-2) 0}.picked li{display:flex;align-items:center;gap:var(--space-2)}
</style>
